-- Trả lương thuyền viên theo từng bill phải thu (docs/mcah-ke-hoach-tra-luong.md phần B). MCAH chưa chuyển tiền trong hệ thống:
-- chỉ ghi nhận đã trả hay chưa, số đã trả từng khoản, ngày trả. Bản ghi sinh lần đầu Chốt; chưa có thì dòng Trả lấy mặc định từ hợp đồng.
CREATE TABLE "seafarer_payout" (
  "id" INTEGER GENERATED BY DEFAULT AS IDENTITY NOT NULL PRIMARY KEY,
  "bill_id" INTEGER NOT NULL UNIQUE REFERENCES "contract_bill" ("id"),
  "status" varchar(10) NOT NULL DEFAULT 'PAID',
  "paid_date" DATE,
  "paid_by" INTEGER REFERENCES "user" ("id"),
  "bill_total_usd" decimal(12,2),
  "version" INTEGER NOT NULL DEFAULT 1,
  "created_by" INTEGER,
  "updated_by" INTEGER,
  "created_at" TIMESTAMP WITHOUT TIME ZONE DEFAULT CURRENT_TIMESTAMP NOT NULL,
  "updated_at" TIMESTAMP WITHOUT TIME ZONE DEFAULT CURRENT_TIMESTAMP NOT NULL,
  CONSTRAINT "seafarer_payout_status_check" CHECK ("status" IN ('UNPAID', 'PAID')),
  CONSTRAINT "seafarer_payout_paid_check" CHECK ("status" <> 'PAID' OR ("paid_date" IS NOT NULL AND "bill_total_usd" IS NOT NULL))
);
CREATE TRIGGER "seafarer_payout_updated_at" BEFORE UPDATE ON "seafarer_payout" FOR EACH ROW EXECUTE FUNCTION touch_updated_at();
CREATE TRIGGER "seafarer_payout_version" BEFORE UPDATE ON "seafarer_payout" FOR EACH ROW EXECUTE FUNCTION bump_row_version();

-- Đủ 14 khoản cố định, một dòng một mã.
CREATE TABLE "seafarer_payout_item" (
  "id" INTEGER GENERATED BY DEFAULT AS IDENTITY NOT NULL PRIMARY KEY,
  "payout_id" INTEGER NOT NULL REFERENCES "seafarer_payout" ("id") ON DELETE CASCADE,
  "item_code" varchar(30) NOT NULL,
  "kind" varchar(10) NOT NULL,
  "default_usd" decimal(12,2) NOT NULL,
  "amount_usd" decimal(12,2) NOT NULL,
  "sort_order" SMALLINT NOT NULL DEFAULT 0,
  UNIQUE ("payout_id", "item_code"),
  CONSTRAINT "seafarer_payout_item_kind_check" CHECK ("kind" IN ('MONTHLY', 'ONE_TIME')),
  CONSTRAINT "seafarer_payout_item_amount_check" CHECK ("amount_usd" >= 0)
);

CREATE TABLE "seafarer_payout_log" (
  "id" INTEGER GENERATED BY DEFAULT AS IDENTITY NOT NULL PRIMARY KEY,
  "payout_id" INTEGER NOT NULL REFERENCES "seafarer_payout" ("id") ON DELETE CASCADE,
  "action" varchar(10) NOT NULL,
  "actor_id" INTEGER REFERENCES "user" ("id"),
  "payload" JSONB,
  "created_at" TIMESTAMP WITHOUT TIME ZONE DEFAULT CURRENT_TIMESTAMP NOT NULL,
  CONSTRAINT "seafarer_payout_log_action_check" CHECK ("action" IN ('PAY', 'UNPAY'))
);
CREATE INDEX "seafarer_payout_log_payout_idx" ON "seafarer_payout_log" ("payout_id");

-- Quyền mới cấp cho vai trò đang có bill.collect; phạm vi dữ liệu theo phạm vi của Yêu cầu thanh toán.
INSERT INTO "role_permission" ("role_id", "permission")
SELECT "role_id", v.p FROM "role_permission", (VALUES ('payout.view'), ('payout.pay')) AS v(p) WHERE "permission" = 'bill.collect'
ON CONFLICT DO NOTHING;
UPDATE "role" SET "scopes" = "scopes" || jsonb_build_object('payout', "scopes" -> 'bill') WHERE "scopes" ? 'bill';
